Algorithm 1 (Conceptual) Admission algorithm:
1 τ ← τ(t);
2 MARK[i] ← false for each i = 1, . . . , n : T i ∈ τ(t);
3 MARK[i] ← true for each i = 1, . . . , n : T i ∈ τ(t);
4 while ∃i : ¬MARK[i] do
5   let i : ¬MARK[i] and ∀k(α k ⊂ α i ∨ MARK[k]);
6   S ← {T k ∈ τ : α k ⊆ α i };
7   sort S by priority;
8   let D be the |S| -|α i | lowest priority tasks in S;
9   τ ← τ \ D;
10  MARK[k] ← true, ∀k : α k = α i ;

Algorithm 2 (Conceptual) Assignment algorithm:
1 ASSIGN[i] ← false for each i = 1, . . . , n : T i ∈ τ;
2 ASSIGN[i] ← true for each i = 1, . . . , n : T i ∈ τ;
3 while ∃i : ¬ASSIGN[i] do
4   let i : ¬ASSIGN[i] and ∀k(α k ⊂ α i ∨ ASSIGN[k]);
5   assign T i to any unused processor in α i ;
6   ASSIGN[i] ← true;

